// @exec: {"yield_time_ms":30000,"max_output_tokens":5000}
const r = await tools.web__run({open:[{ref_id:"https://raw.githubusercontent.com/agent-ecosystem/agent-docs-spec/main/SPEC.md"}],response_length:"long"});
const raw = typeof r === "string" ? r : JSON.stringify(r);
store("ec6_raw_response", raw);
const chars = [...raw].length;
const lines = raw.split(/\r?\n/);
let openFence = null;
const fenceEvents = [];
for (let i = 0; i < lines.length; i++) {
  const match = lines[i].match(/^\s*(`{3,}|~{3,})/);
  if (!match) continue;
  const marker = match[1];
  const char = marker[0];
  const length = marker.length;
  if (openFence && openFence.char === char && length >= openFence.length) {
    fenceEvents.push({kind:"close", line:i+1, marker});
    openFence = null;
  } else if (!openFence) {
    openFence = {char, length, line:i+1, marker};
    fenceEvents.push({kind:"open", line:i+1, marker});
  }
}
const lower = raw.toLowerCase();
const explicitMarkers = [
  "[truncated]",
  "truncated",
  "cut off",
  "content omitted",
  "output omitted",
  "response too large",
  "maximum response",
  "…",
  "..."
].filter(m => lower.includes(m.toLowerCase()));
const headings = lines.map((line,index) => ({line,index: index+1})).filter(x => /^#{1,6}\s/.test(x.line));
const lastNonEmptyIndex = [...lines].map((line,i)=>({line,i})).filter(x=>x.line.trim()).at(-1);
const tail = [...raw].slice(-50).join("");
const result = {
  value_type:typeof r,
  result_length_utf16:raw.length,
  response_characters_unicode_codepoints:chars,
  estimated_tokens_chars_div_4:Math.round(chars / 4),
  line_count:lines.length,
  last_50_characters:tail,
  last_nonempty_line:lastNonEmptyIndex ? {line:lastNonEmptyIndex.i+1,text:lastNonEmptyIndex.line} : null,
  last_heading:headings.at(-1) ?? null,
  markdown_fence_events_count:fenceEvents.length,
  markdown_fences_unclosed:openFence,
  explicit_possible_truncation_markers:explicitMarkers,
  starts_with:raw.slice(0,250),
  ends_with:raw.slice(-500)
};
text(JSON.stringify(result, null, 2));

const raw = load("ec6_raw_response");
const physicalLines = String(raw).split(/\r?\n/);
const sourceLines = physicalLines.map((rawLine, physicalIndex) => {
  const m = rawLine.match(/^L(\d+):\s?(.*)$/);
  return m ? {physicalLine: physicalIndex + 1, sourceLine: Number(m[1]), text: m[2]} : null;
}).filter(Boolean);
const fenceLines = sourceLines.filter(x => /^\s*(`{3,}|~{3,})/.test(x.text));
let open = null;
const events = [];
for (const x of fenceLines) {
  const m = x.text.match(/^\s*(`{3,}|~{3,})/);
  const marker = m[1], char = marker[0], length = marker.length;
  if (open && open.char === char && length >= open.length) {
    events.push({kind:"close", sourceLine:x.sourceLine, marker});
    open = null;
  } else if (!open) {
    open = {char,length,sourceLine:x.sourceLine,marker};
    events.push({kind:"open", sourceLine:x.sourceLine,marker});
  }
}
const truncMatches = [...String(raw).matchAll(/truncated/ig)].map(m => ({
  index:m.index,
  context:String(raw).slice(Math.max(0,m.index-80),m.index+100)
}));
const labels = sourceLines.map(x => x.sourceLine);
text(JSON.stringify({
  source_line_labels:{first:labels[0],last:labels.at(-1),count:labels.length,consecutive:labels.every((n,i)=>i===0||n===labels[i-1]+1)},
  source_code_fence_lines:fenceLines,
  source_fence_events:events,
  unclosed_source_fence:open,
  truncation_word_occurrences:truncMatches,
  final_source_line:sourceLines.at(-1),
  final_50:[...String(raw)].slice(-50).join("")
}, null, 2));

