const raw = String(load("ec6_raw_response"));
const sourceText = raw.split(/\r?\n/)
  .map(line => line.replace(/^L\d+:\s?/, ""))
  .filter((line, i) => i >= 2)
  .join("\n");
const sourceOnlyLines = raw.split(/\r?\n/).filter(line => /^L\d+:\s?/.test(line));
const sourceOnly = sourceOnlyLines.map(line => line.replace(/^L\d+:\s?/, "")).join("\n");
text(JSON.stringify({
  full_response_chars:[...raw].length,
  labeled_source_segment_chars:[...sourceOnly].length,
  tool_framing_and_line_label_overhead:[...raw].length-[...sourceOnly].length,
  full_response_word_count:(raw.match(/\S+/g) ?? []).length,
  source_segment_word_count:(sourceOnly.match(/\S+/g) ?? []).length
}, null, 2));
